  "description": {
    "subtitle": "1.1 Overview of Major Changes for Billing in S4",
    "content": [
      {
        "area": "Billing Number Range",
        "before": "Only Numeric; with each GB, their own logic",
        "after": "Billing Number Range is Alpha Numeric according to standardized central RB concept"
      },
      {
        "area": "Billing and Output Types",
        "before": "GB Specific Billing types & Output types",
        "after": "New Billing Types and Output Types according to standardized central RB concept"
      },
      {
        "area": "Invoice Layout",
        "before": "Each GB handled on their own",
        "after": "New Layout of the Invoice form @RB level using ADOBE forms which is more flexible and offers more options"
      },
      {
        "area": "Service Invoicing",
        "before": "Only DIEN Materials are used",
        "after": "YSER + SERV+ BUND Materials are used due to standardized new RB concept"
      },
      {
        "area": "Billing of Costs (cost charging)",
        "before": "W/o SD process but with FI-Billing",
        "after": "Use of standardized RB concept for DIEN part-numbers and SD process"
      },
      {
        "area": "Order Reasons",
        "before": "Order Reasons were mandatory for SD-FI account determination",
        "after": "Account Assignment Group setting in Material- and Customer Master Data for SD-FI account determination due to standardized RB concept"
      },
      {
        "area": "Downpayment",
        "before": "Separate Down Payment item in order (condition-based solution)",
        "after": "Billing Plan on Billing Plan relevant item categories"
      },
      {
        "area": "NSGS (Non-Stock Goods, non-Rexroth goods)",
        "before": "(Germany only) use of APM Dummy numbers DCCD 0668; Partly w/o SD process but with FI-Billing",
        "after": "Use of standardized RB concept for NSGS part-numbers; SD process"
      }
