            "bom_kit_returns": [
              "Cancel price-relevant header item.",
              "Cancel higher-level assignment.",
              "Handle only delivery-relevant items.",
              "Handle price-related topics manually for subitems."
            ],
            "indradrive_returns": {
              "challenges": "ARM cannot handle HPOS/UPOS cases effectively, and current solutions are suboptimal.",
              "scenarios": [
                {
                  "scenario": "Transfer to Free Available Stock",
                  "handling": [
                    "Delete Higher Lower Level Item Assignment via Reuse Layer Copy Control.",
                    "Use Item Category YVR2 for Main Item and YVR4 for Sub Items.",
                    "Handle only Main Item in Logistical Follow-Up; Sub Items remain in Indradrive Storage."
                  ]
                },
                {
                  "scenario": "Transfer to Scrap",
                  "handling": "Scrapping of Indradrive items must be done manually."
                },
                {
                  "scenario": "Send Back to Customer",
                  "handling": "To be avoided. If customer sends back Indradrive, double-check before GR. If NOK, send back to customer without ARM process."
                },
                {
                  "scenario": "Ship to Vendor",
                  "handling": [
                    "Use Scenario Transfer to Free Available Stock.",
                    "Create separate Return PO without connection to ARM process."
                  ]
                }
              ],
              "notes": [
                "Resale of Indradrive via SFS Scenario is currently not possible until SFS process implementation after DCPL Golive.",
                "Indradrive Return Process will be re-investigated and improved within the scope of the 'plant template'."
              ]
            }
          }
        }
      },
      {
        "section": "Monitoring and Final Steps",
        "details": {
